use std::{
    io::Write,
    process::{Command, Stdio},
};

const NO_VERSION_HEX: &str = "";

const REQUEST_HEX: &str = "";
const RESPONSE_HEX: &str = "";

#[cfg(test)]
fn run(input: &str) -> (String, bool) {
    let mut child = Command::new(env!("CARGO_BIN_EXE_ttlv_parser"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .spawn()
        .unwrap();
    child
        .stdin
        .take()
        .unwrap()
        .write_all(input.as_bytes())
        .unwrap();
    let out = child.wait_with_output().unwrap();
    (String::from_utf8(out.stdout).unwrap(), out.status.success())
}

#[test]
fn characterization_ttlv_parser_quit() {
    let (out, ok) = run("quit\n");
    assert_eq!(
        out,
        "TTLV Parser - Enter hex strings (or 'quit' to exit)\n> "
    );
    assert!(ok);
}

#[test]
fn characterization_ttlv_parser_bad_inputs() {
    let (out, ok) = run("\nzz\n0102\nexit\n");
    assert_eq!(
        out,
        "TTLV Parser - Enter hex strings (or 'quit' to exit)\n> > ERROR parsing hex string: Invalid character 'z' at position 0\n> ERROR: Unsupported KMIP version: 2147483647.2147483647\n> "
    );
    assert!(ok);
}

#[test]
fn characterization_ttlv_parser_no_version() {
    let (out, ok) = run(&format!("{NO_VERSION_HEX}\nquit\n"));
    assert_eq!(
        out,
        "TTLV Parser - Enter hex strings (or 'quit' to exit)\n> ERROR: Unsupported KMIP version: 2147483647.2147483647\n> "
    );
    assert!(ok);
}

#[test]
fn characterization_ttlv_parser_request_and_response() {
    let (out, ok) = run(&format!("{REQUEST_HEX}\n{RESPONSE_HEX}\nquit\n"));
    assert!(out.starts_with("TTLV Parser - Enter hex strings (or 'quit' to exit)\n> \nTTLV ==> \n\nTTLV {\n    tag: \"RequestMessage\""));
    assert_eq!(out.matches("Request ==>\n\n").count(), 1);
    assert_eq!(out.matches("Response ==>\n\n").count(), 1);
    assert_eq!(out.matches("\nSUCCESS\n").count(), 2);
    assert!(!out.contains("ERROR"));
    assert!(ok);
}
